import Foundation

// MARK: - Storage (Copy-on-Write backing)

/// Private backing store for AudioBuffer's samples array.
///
/// Marked @unchecked Sendable because:
/// - This class is `private` and never escapes AudioBuffer's implementation.
/// - After initialisation the `samples` array is never mutated; AudioBuffer's
///   COW pattern creates a new storage instance on every write, so the stored
///   array is effectively immutable for the lifetime of each storage object.
private final class AudioBufferStorage: @unchecked Sendable {
    let samples: [Float]

    init(samples: [Float]) {
        self.samples = samples
    }
}

// MARK: - AudioBuffer

/// A value type that holds a single chunk of PCM audio data.
///
/// Samples are stored with copy-on-write semantics: multiple `AudioBuffer`
/// values can share the same underlying `[Float]` allocation until one of
/// them is mutated.
public struct AudioBuffer: Sendable {
    // MARK: Public properties

    /// Playback / capture sample rate in Hz (e.g. 16 000, 44 100).
    public let sampleRate: Double

    /// Number of interleaved audio channels (1 = mono, 2 = stereo, …).
    public let channelCount: Int

    /// Session-relative timestamp in seconds (seconds elapsed since recording start).
    ///
    /// Defaults to `0`; infrastructure layers set the real value from `AVAudioTime.hostTime`
    /// normalized against the session's start tick via `MachClock.ticksToSeconds(_:)`.
    public let timestamp: TimeInterval

    /// The PCM samples, with copy-on-write semantics.
    public var samples: [Float] {
        get { storage.samples }
        set {
            precondition(channelCount > 0, "channelCount must be greater than 0")
            precondition(newValue.count % channelCount == 0, "samples count must be a multiple of channelCount")
            storage = AudioBufferStorage(samples: newValue)
        }
    }

    // MARK: Private COW storage

    private var storage: AudioBufferStorage

    // MARK: Initialiser

    /// Creates a new `AudioBuffer`.
    ///
    /// - Parameters:
    ///   - sampleRate: Sample rate in Hz.
    ///   - channelCount: Number of audio channels.
    ///   - samples: Interleaved PCM samples in 32-bit float format.
    ///   - timestamp: Session-relative timestamp in seconds. Defaults to `0`; infrastructure
    ///     layers set the real value from `AVAudioTime.hostTime` via `MachClock.ticksToSeconds`.
    public init(sampleRate: Double, channelCount: Int, samples: [Float], timestamp: TimeInterval = 0) {
        precondition(channelCount > 0, "channelCount must be greater than 0")
        precondition(samples.count % channelCount == 0, "samples count must be a multiple of channelCount")
        self.sampleRate = sampleRate
        self.channelCount = channelCount
        self.timestamp = timestamp
        storage = AudioBufferStorage(samples: samples)
    }
}

