1	import Accelerate
2	import Domain
3	import Foundation
4	import GRDB
5	import Logging
6	@preconcurrency import NaturalLanguage
7	
8	public struct CachedResult: Sendable {
9	    public let title: String
10	    public let body: String
11	    public let sourceURL: String?
12	    public let providerID: String
13	    public let relevanceScore: Double
14	}
15	
16	public actor GRDBContextCache {
17	    private let dbPool: any DatabaseWriter & Sendable
18	    private let logger = AppLogger.for(category: "ContextCache")
19	    private var nlEmbedding: NLEmbedding?
20	
21	    public init(databasePath: URL?) throws {
22	        if let path = databasePath {
23	            try FileManager.default.createDirectory(
24	                at: path.deletingLastPathComponent(),
25	                withIntermediateDirectories: true
26	            )
27	            dbPool = try DatabasePool(path: path.path)
28	        } else {
29	            dbPool = try DatabaseQueue()
30	        }
31	        try GRDBMigrations.migrator().migrate(dbPool)
32	    }
33	
34	    public func get(query: String, providerID: String, ttlSeconds: Int) async throws -> [CachedResult]? {
35	        try await dbPool.read { db in
36	            let rows = try Row.fetchAll(
37	                db, sql: GRDBSQL.selectCached,
38	                arguments: [query, providerID, ttlSeconds]
39	            )
40	            guard !rows.isEmpty else { return nil }
41	            return rows.map { row in
42	                CachedResult(
43	                    title: row["title"] ?? "",
44	                    body: row["body"] ?? "",
45	                    sourceURL: row["source_url"],
46	                    providerID: row["provider_id"] ?? "",
47	                    relevanceScore: row["relevance_score"] ?? 0
48	                )
49	            }
50	        }
51	    }
52	
53	    public func put(query: String, results: [CachedResult], emptyProviderID: String = "") async throws {
54	        let providerIDsToEvict: Set<String> = results.isEmpty
55	            ? (emptyProviderID.isEmpty ? [] : [emptyProviderID])
56	            : Set(results.map(\.providerID))
57	
58	        let embeddingBlob: Data? = await embeddingVector(for: query).map { vector in
59	            vector.withUnsafeBufferPointer { Data(buffer: $0) }
60	        }
61	
62	        try await dbPool.write { db in
63	            for pid in providerIDsToEvict {
64	                try db.execute(sql: GRDBSQL.deleteCached, arguments: [query, pid])
65	            }
66	
67	            guard !results.isEmpty else {
68	                try db.execute(sql: GRDBSQL.insertCached, arguments: [
69	                    query, "", "", nil as String?, emptyProviderID, 0.0, embeddingBlob,
70	                ])
71	                return
72	            }
73	
74	            for result in results {
75	                try db.execute(sql: GRDBSQL.insertCached, arguments: [
76	                    query, result.title, result.body, result.sourceURL,
77	                    result.providerID, result.relevanceScore, embeddingBlob,
78	                ])
79	            }
80	        }
81	    }
82	
83	    public func getSemantic(
84	        query: String, providerID: String,
85	        matcher: SemanticCacheMatcher,
86	        threshold: Double,
87	        ttlSeconds: Int
88	    ) async throws -> [CachedResult]? {
89	        let rows: [Row] = try await dbPool.read { db in
90	            try Row.fetchAll(db, sql: GRDBSQL.selectDistinctQueriesWithEmbeddings, arguments: [providerID])
91	        }
92	        guard !rows.isEmpty else { return nil }
93	
94	        let matchedQuery: String? = if let queryVector = await embeddingVector(for: query) {
95	            bestEmbeddingMatch(queryVector: queryVector, rows: rows, threshold: threshold)
96	        } else {
97	            bestFuzzyMatch(query: query, rows: rows, matcher: matcher, threshold: threshold)
98	        }
99	        guard let matchedQuery else { return nil }
100	        return try await get(query: matchedQuery, providerID: providerID, ttlSeconds: ttlSeconds)
101	    }
102	
103	    private func bestFuzzyMatch(
104	        query: String, rows: [Row],
105	        matcher: SemanticCacheMatcher, threshold: Double
106	    ) -> String? {
107	        var bestMatch: (query: String, score: Double)?
108	        for row in rows {
109	            guard let cached: String = row["query_text"] else { continue }
110	            let score = matcher.similarity(between: query, and: cached)
111	            if score >= threshold, bestMatch.map({ score > $0.score }) ?? true {
112	                bestMatch = (cached, score)
113	            }
114	        }
115	        return bestMatch?.query
116	    }
117	
118	    private func bestEmbeddingMatch(
119	        queryVector: [Double], rows: [Row], threshold: Double
120	    ) -> String? {
121	        var bestMatch: (query: String, score: Double)?
122	        for row in rows {
123	            guard let cached: String = row["query_text"],
